"""Wire ``on_knowledge_query`` / ``modify_knowledge_query`` before index search."""

from __future__ import annotations

import structlog

from rasa.mantle.hooks.constants import POINT_KNOWLEDGE_QUERY
from rasa.mantle.hooks.exceptions import HookExecutionError
from rasa.mantle.hooks.payloads import KnowledgeQueryPayload
from rasa.mantle.hooks.registry import HookRegistry
from rasa.mantle.hooks.runner import run_modify, run_observers
from rasa.mantle.hooks.utils import hook_identity

structlogger = structlog.get_logger()


async def apply_knowledge_query_hooks(registry: HookRegistry, query: str) -> str:
    """Run ``on_knowledge_query`` / ``modify_knowledge_query`` for one search.

    Observers fire-and-forget. The modify lane may rewrite ``query``. This
    point has no intentional control signals; unexpected crashes/timeouts
    raise ``HookExecutionError`` (fail-closed) so the caller skips the search.

    Raises:
        HookExecutionError: When the fail-closed modify hook crashes or times
            out.
    """
    # No registered hooks for this point — skip payload/runner setup.
    if (
        not registry.observers(POINT_KNOWLEDGE_QUERY)
        and registry.modifier(POINT_KNOWLEDGE_QUERY) is None
    ):
        return query

    try:
        sender_id, channel = hook_identity()
    except LookupError:
        # Live turns establish MessageTurnContext; missing context is misuse
        # (e.g. isolated unit tests). Keep the query unmodified.
        structlogger.warning(
            "mantle.hooks.knowledge_query.skipped_no_turn_context",
        )
        return query

    payload = KnowledgeQueryPayload(
        sender_id=sender_id,
        channel=channel,
        query=query,
    )
    run_observers(registry, POINT_KNOWLEDGE_QUERY, payload)
    result = await run_modify(registry, POINT_KNOWLEDGE_QUERY, payload)

    modified = result.payload
    if not isinstance(modified, KnowledgeQueryPayload):
        raise HookExecutionError(
            "modify_knowledge_query returned an unexpected payload type."
        )
    return modified.query
